contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Attempt to withdraw 'amt' from c by calling c.withdraw(amt) as owner (this contract).
    // Verify balance movement corresponds to success/failure of the call.
    function run(uint amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // ensure this contract has enough balance to be meaningful later (not strictly required)
        require(address(this).balance >= 0);

        // Observe before state
        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;

        // Perform the state-changing call on c: only-owner function withdraw(uint)
        bool reverted;
        c.withdraw(amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after state
        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;

        // General property:
        // - c.withdraw never increases C's balance;
        // - if the call succeeded, C's balance decreased by exactly amt and this contract's balance increased by exactly amt;
        // - if the call reverted, balances remain unchanged.
        assert((!reverted && afterC + amt == beforeC && afterSelf == beforeSelf + amt)
            || (reverted && afterC == beforeC && afterSelf == beforeSelf));
    }

    // allow receiving ETH when c.transfer sends funds here
    receive() external payable {}
}

